std::string g_iniPath;
struct FileStamp
{
    FILETIME write{};
    bool     valid = false;
};
FileStamp g_iniStamp;
bool      g_haveIni = false;

std::vector<std::pair<std::string, std::string>> g_overrides;
double g_clock      = 0.0;
